    66→// LoadEntireSettings loads the Entire settings from .entire/settings.json,
    67→// then applies any overrides from .entire/settings.local.json if it exists.
    68→// Returns default settings if neither file exists.
    69→// Works correctly from any subdirectory within the repository.
    70→func LoadEntireSettings() (*EntireSettings, error) {
    71→	settings := &EntireSettings{
    72→		Strategy: strategy.DefaultStrategyName,
    73→		Enabled:  true, // Default to enabled
    74→	}
    75→
    76→	// Get absolute paths for settings files
    77→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
    78→	if err != nil {
    79→		settingsFileAbs = EntireSettingsFile // Fallback to relative
    80→	}
    81→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
    82→	if err != nil {
    83→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
    84→	}
    85→
    86→	// Load base settings
    87→	data, err := os.ReadFile(settingsFileAbs) //nolint:gosec // path is from AbsPath or constant
    88→	if err != nil {
    89→		if !os.IsNotExist(err) {
    90→			return nil, fmt.Errorf("reading settings file: %w", err)
    91→		}
    92→		// File doesn't exist, continue with defaults
    93→	} else {
    94→		if err := json.Unmarshal(data, settings); err != nil {
    95→			return nil, fmt.Errorf("parsing settings file: %w", err)
    96→		}
    97→	}
    98→
    99→	// Apply local overrides if they exist
   100→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
   101→	if err != nil {
   102→		if !os.IsNotExist(err) {
   103→			return nil, fmt.Errorf("reading local settings file: %w", err)
   104→		}
   105→		// Local file doesn't exist, continue without overrides
   106→	} else {
   107→		if err := mergeSettingsJSON(settings, localData); err != nil {
   108→			return nil, fmt.Errorf("merging local settings: %w", err)
   109→		}
   110→	}
   111→
   112→	// Apply defaults if not set
   113→	if settings.Strategy == "" {
   114→		settings.Strategy = strategy.DefaultStrategyName
   115→	}
   116→	settings.Strategy = strategy.NormalizeStrategyName(settings.Strategy)
   117→
   118→	return settings, nil
   119→}
