   121→// mergeSettingsJSON merges JSON data into existing settings.
   122→// Only non-zero values from the JSON override existing settings.
   123→func mergeSettingsJSON(settings *EntireSettings, data []byte) error {
   124→	// Parse into a map to check which fields are present
   125→	var raw map[string]json.RawMessage
   126→	if err := json.Unmarshal(data, &raw); err != nil {
   127→		return fmt.Errorf("parsing JSON: %w", err)
   128→	}
   129→
   130→	// Override strategy if present and non-empty
   131→	if strategyRaw, ok := raw["strategy"]; ok {
   132→		var s string
   133→		if err := json.Unmarshal(strategyRaw, &s); err != nil {
   134→			return fmt.Errorf("parsing strategy field: %w", err)
   135→		}
   136→		if s != "" {
   137→			settings.Strategy = s
   138→		}
   139→	}
   140→
   141→	// Override enabled if present
   142→	if enabledRaw, ok := raw["enabled"]; ok {
   143→		var e bool
   144→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
   145→			return fmt.Errorf("parsing enabled field: %w", err)
   146→		}
   147→		settings.Enabled = e
   148→	}
   149→
   150→	// Override local_dev if present
   151→	if localDevRaw, ok := raw["local_dev"]; ok {
   152→		var ld bool
   153→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
   154→			return fmt.Errorf("parsing local_dev field: %w", err)
   155→		}
   156→		settings.LocalDev = ld
   157→	}
   158→
   159→	// Override log_level if present and non-empty
   160→	if logLevelRaw, ok := raw["log_level"]; ok {
   161→		var ll string
   162→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
   163→			return fmt.Errorf("parsing log_level field: %w", err)
   164→		}
   165→		if ll != "" {
   166→			settings.LogLevel = ll
   167→		}
   168→	}
   169→
   170→	// Merge strategy_options if present
   171→	if optionsRaw, ok := raw["strategy_options"]; ok {
   172→		var opts map[string]interface{}
   173→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
   174→			return fmt.Errorf("parsing strategy_options field: %w", err)
   175→		}
   176→		if settings.StrategyOptions == nil {
   177→			settings.StrategyOptions = opts
   178→		} else {
   179→			for k, v := range opts {
   180→				settings.StrategyOptions[k] = v
   181→			}
   182→		}
   183→	}
   184→
   185→	// Override agent if present and non-empty
   186→	if agentRaw, ok := raw["agent"]; ok {
   187→		var a string
   188→		if err := json.Unmarshal(agentRaw, &a); err != nil {
   189→			return fmt.Errorf("parsing agent field: %w", err)
   190→		}
   191→		if a != "" {
   192→			settings.Agent = a
   193→		}
   194→	}
   195→
   196→	// Override agent_auto_detect if present
   197→	if autoDetectRaw, ok := raw["agent_auto_detect"]; ok {
   198→		var ad bool
   199→		if err := json.Unmarshal(autoDetectRaw, &ad); err != nil {
   200→			return fmt.Errorf("parsing agent_auto_detect field: %w", err)
   201→		}
   202→		settings.AgentAutoDetect = &ad
   203→	}
   204→
   205→	// Merge agent_options if present
   206→	if agentOptsRaw, ok := raw["agent_options"]; ok {
   207→		var opts map[string]interface{}
   208→		if err := json.Unmarshal(agentOptsRaw, &opts); err != nil {
   209→			return fmt.Errorf("parsing agent_options field: %w", err)
   210→		}
   211→		if settings.AgentOptions == nil {
   212→			settings.AgentOptions = opts
   213→		} else {
   214→			for k, v := range opts {
   215→				settings.AgentOptions[k] = v
   216→			}
   217→		}
   218→	}
   219→
   220→	// Override telemetry if present
   221→	if telemetryRaw, ok := raw["telemetry"]; ok {
   222→		var t bool
   223→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
   224→			return fmt.Errorf("parsing telemetry field: %w", err)
   225→		}
   226→		settings.Telemetry = &t
   227→	}
   228→
   229→	return nil
   230→}
