   277→// GetStrategy returns the configured strategy instance.
   278→// Falls back to default if the configured strategy is not found.
   279→//
   280→//nolint:ireturn // Factory pattern requires returning the interface
   281→func GetStrategy() strategy.Strategy {
   282→	settings, err := LoadEntireSettings()
   283→	if err != nil {
   284→		// Fall back to default on error
   285→		logging.Info(context.Background(), "falling back to default strategy - failed to load settings",
   286→			slog.String("error", err.Error()))
   287→		return strategy.Default()
   288→	}
   289→
   290→	s, err := strategy.Get(settings.Strategy)
   291→	if err != nil {
   292→		// Fall back to default if strategy not found
   293→		logging.Info(context.Background(), "falling back to default strategy - configured strategy not found",
   294→			slog.String("configured", settings.Strategy),
   295→			slog.String("error", err.Error()))
   296→		return strategy.Default()
   297→	}
   298→
   299→	return s
   300→}
   301→
   302→// GetAgent returns the configured or detected agent.
   303→// Resolution order:
   304→// 1. Explicit agent in settings
   305→// 2. Auto-detect if enabled (default)
   306→// 3. Fall back to default agent
   307→//
   308→//nolint:ireturn // Factory pattern requires returning the interface
   309→func GetAgent() (agent.Agent, error) {
   310→	settings, err := LoadEntireSettings()
   311→	if err != nil {
   312→		// No settings file, try auto-detect then default
   313→		if ag, detectErr := agent.Detect(); detectErr == nil {
   314→			return ag, nil
   315→		}
   316→		return agent.Default(), nil
   317→	}
   318→
   319→	// Explicit agent configured
   320→	if settings.Agent != "" {
   321→		ag, err := agent.Get(agent.AgentName(settings.Agent))
   322→		if err != nil {
   323→			return nil, fmt.Errorf("getting configured agent: %w", err)
   324→		}
   325→		return ag, nil
   326→	}
   327→
   328→	// Auto-detect if enabled (default true for backwards compat)
   329→	autoDetect := settings.AgentAutoDetect == nil || *settings.AgentAutoDetect
   330→	if autoDetect {
   331→		if ag, detectErr := agent.Detect(); detectErr == nil {
   332→			return ag, nil
   333→		}
   334→	}
   335→
   336→	// Fall back to default
   337→	return agent.Default(), nil
   338→}
